/** Provider uses the real planner session and its borrowed authorities. */
class PackedRegionProviderLifecycleTest {

	@Test
	void positiveProviderReceivesRegionFactoryAndAllHandlesExpireWithSession() {
		AtomicReference<PackedPhysicalRegion.Factory> factory = new AtomicReference<>();
		AtomicReference<PackedPhysicalRegion.Result<PackedPhysicalRegion>> opened = new AtomicReference<>();
		AtomicReference<PackedPhysicalRegion> region = new AtomicReference<>();
		AtomicReference<PackedPhysicalRegion.Occurrence> root = new AtomicReference<>();
		AtomicReference<PackedPhysicalRegion.Coverage> coverage = new AtomicReference<>();
		AtomicReference<PackedPhysicalRegion.Quote> quote = new AtomicReference<>();
		AtomicReference<PackedPhysicalRegion.Vector> vector = new AtomicReference<>();
		AtomicReference<PackedProviderWork> borrowedWork = new AtomicReference<>();
		AtomicReference<PackedProviderMemory> borrowedMemory = new AtomicReference<>();
		AtomicInteger callbacks = new AtomicInteger();
		PackedCostModel model = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				throw new AssertionError("the real provider session owns costing");
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query, PackedProviderWork work,
					PackedProviderMemory memory) {
				borrowedWork.set(work);
				borrowedMemory.set(memory);
				return new PackedCostSession() {
					@Override
					public void bindPhysicalRegions(PackedPhysicalRegion.Factory bound) {
						factory.set(bound);
					}

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						callbacks.incrementAndGet();
						if (region.get() == null) {
							assertNotNull(factory.get(),
									"an admitted provider must receive the planner-owned region factory");
							assertTrue(work.remainingWorkUnits() > 0);
							PackedPhysicalRegion.Result<PackedPhysicalRegion> attempt = factory.get().open();
							assertEquals(PackedPhysicalRegion.Status.READY, attempt.status());
							opened.set(attempt);
							region.set(attempt.value());
							root.set(region.get().root());
							PackedPhysicalRegion.Result<PackedPhysicalRegion.Coverage> proof = region.get()
									.cover(root.get(),
											new PackedPhysicalRegion.Occurrence[] { root.get() });
							assertEquals(PackedPhysicalRegion.Status.READY, proof.status());
							coverage.set(proof.value());
							assertEquals(2, coverage.get().boundaryCount());
							long before = work.remainingWorkUnits();
							var quoted = coverage.get().quote(localCost(4.0d));
							var first = coverage.get().boundaryCost(0, cost(2.0d));
							var second = coverage.get().boundaryCost(1, cost(3.0d));
							assertEquals(PackedPhysicalRegion.Status.READY, quoted.status());
							assertEquals(PackedPhysicalRegion.Status.READY, first.status());
							assertEquals(PackedPhysicalRegion.Status.READY, second.status());
							quote.set(quoted.value());
							var composed = coverage.get()
									.composeInclusive(quote.get(),
											new PackedPhysicalRegion.BoundaryCost[] { first.value(), second.value() });
							assertEquals(PackedPhysicalRegion.Status.READY, composed.status());
							vector.set(composed.value());
							assertEquals(9.0d, vector.get().point(PackedCostDimensionRegistry.SOURCE_ROW_EVENTS));
							assertTrue(work.remainingWorkUnits() < before,
									"actual provider quotation uses shared admission");
						}
						output.setRows(1.0d, 1.0d);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						estimateLeaf(relationId, context, output);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
					}

					@Override
					public void close() {
						assertEquals(2, coverage.get().boundaryCount(),
								"handles remain usable during provider cleanup");
						assertSame(coverage.get(), quote.get().coverage());
						assertSame(coverage.get(), vector.get().coverage());
					}
				};
			}
		};
		TupleExpr source = new Join(pattern("a"), pattern("b"));

		PackedPlanningResult result = PackedCascadesPlanner.optimize(source, OptimizationGoal.root(),
				new PackedPlannerLimits(100_000L, Long.MAX_VALUE, 10_000_000L), model);

		assertNotNull(result.selectedPlan());
		assertTrue(callbacks.get() > 0, "a positive provider callback must actually run");
		assertNotNull(coverage.get());
		assertThrows(IllegalStateException.class, () -> factory.get().open());
		assertThrows(IllegalStateException.class, () -> opened.get().status());
		assertThrows(IllegalStateException.class, () -> region.get().root());
		assertThrows(IllegalStateException.class, () -> root.get().relationId());
		assertThrows(IllegalStateException.class, () -> coverage.get().boundaryCount());
		assertThrows(IllegalStateException.class, () -> quote.get().coverage());
		assertThrows(IllegalStateException.class, () -> vector.get().coverage());
		assertThrows(IllegalStateException.class, () -> borrowedWork.get().remainingWorkUnits());
		assertThrows(IllegalStateException.class, () -> borrowedWork.get().tryReserve(0));
		assertThrows(IllegalStateException.class, () -> borrowedMemory.get().tryReserve(0));
	}

	@Test
	void sameThrowableFromCallbackAndCloseKeepsPrimaryIdentity() {
		assertSameFailureFromProviderAndClose("callback");
		assertSameFailureFromProviderAndClose("callback", new QueryInterruptedException("same cancellation"));
		assertSameFailureFromProviderAndClose("callback", new AssertionError("same provider error"));
	}

	@Test
	void sameThrowableFromEarlyBindingAndCloseKeepsPrimaryIdentity() {
		assertSameFailureFromProviderAndClose("memory");
	}

	@Test
	void sameThrowableFromRegionBindingAndCloseKeepsPrimaryIdentity() {
		assertSameFailureFromProviderAndClose("region");
	}

	@Test
	void sameWorkRefusalFromProviderAndCloseIsNotConvertedToFallback() {
		assertSameFailureFromProviderAndClose("callback", new PackedProviderWork.Exhausted());
		assertSameFailureFromProviderAndClose("memory", new PackedProviderWork.Exhausted());
	}

	@Test
	void workRefusalFromCloseAloneIsNotConvertedToFallback() {
		assertSameFailureFromProviderAndClose("close", new PackedProviderWork.Exhausted());
	}

	@Test
	void checkedCallbackThrowableStillClosesAndPreservesIdentity() {
		assertSameFailureFromProviderAndClose("callback", new IOException("same checked callback failure"));
	}

	@Test
	void checkedEarlyBindingThrowableStillClosesAndPreservesIdentity() {
		assertSameFailureFromProviderAndClose("memory", new IOException("same checked binding failure"));
	}

	@Test
	void checkedCallbackAndDistinctCleanupRemainPrimaryAndSuppressed() {
		assertFailureFromProviderAndClose("callback", new IOException("checked provider failure"),
				new IOException("checked close failure"));
	}

	private static void assertSameFailureFromProviderAndClose(String phase) {
		assertSameFailureFromProviderAndClose(phase,
				new IllegalStateException("same failure from " + phase + " and close"));
	}

	private static void assertSameFailureFromProviderAndClose(String phase, Throwable failure) {
		assertFailureFromProviderAndClose(phase, failure, failure);
	}

	private static void assertFailureFromProviderAndClose(String phase, Throwable failure, Throwable closeFailure) {
		AtomicInteger opens = new AtomicInteger();
		AtomicInteger callbacks = new AtomicInteger();
		AtomicInteger closes = new AtomicInteger();
		PackedCostModel model = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				throw new AssertionError("session owns estimation");
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				opens.incrementAndGet();
				return new PackedCostSession() {
					@Override
					public void bindProviderMemory(PackedProviderMemory memory) {
						if (phase.equals("memory")) {
							throwFailure(failure);
						}
					}

					@Override
					public void bindPhysicalRegions(PackedPhysicalRegion.Factory factory) {
						if (phase.equals("region")) {
							throwFailure(failure);
						}
					}

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						callbacks.incrementAndGet();
						if (phase.equals("close")) {
							output.setRows(1.0d, 1.0d);
							return;
						}
						throwFailure(failure);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						estimateLeaf(relationId, context, output);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
						estimateLeaf(relationId, context, output);
					}

					@Override
					public void close() {
						closes.incrementAndGet();
						throwFailure(closeFailure);
					}
				};
			}
		};
		Throwable actual = assertThrows(Throwable.class, () -> PackedCascadesPlanner.optimize(
				new Join(pattern("a"), pattern("b")), OptimizationGoal.root(),
				new PackedPlannerLimits(100_000L, Long.MAX_VALUE, 10_000_000L), model));
		assertSame(failure, actual, "cleanup must not replace the primary object");
		assertEquals(1, opens.get());
		if (phase.equals("close")) {
			assertTrue(callbacks.get() > 0);
		} else {
			assertEquals(phase.equals("callback") ? 1 : 0, callbacks.get());
		}
		assertEquals(1, closes.get());
		assertEquals(failure == closeFailure ? 0 : 1, actual.getSuppressed().length);
		if (failure != closeFailure) {
			assertSame(closeFailure, actual.getSuppressed()[0]);
		}
	}

	@SuppressWarnings("unchecked")
	private static <T extends Throwable> void throwFailure(Throwable failure) throws T {
		throw (T) failure;
	}

	@Test
	void failedRegionProviderKeepsFailureAndCleanupIdentity() {
		assertProviderFailure(new IllegalStateException("actual provider failure"));
		assertProviderFailure(new QueryInterruptedException("actual provider cancellation"));
		assertProviderFailure(new AssertionError("actual provider error"));
	}

	@Test
	void failureWhileBindingFactoryClosesSessionAndPreservesBothFailures() {
		IllegalStateException failure = new IllegalStateException("factory binding failed");
		IllegalStateException cleanup = new IllegalStateException("session cleanup failed");
		AtomicReference<PackedPhysicalRegion.Factory> borrowed = new AtomicReference<>();
		PackedCostModel model = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return 1.0d;
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {
					@Override
					public void bindPhysicalRegions(PackedPhysicalRegion.Factory factory) {
						borrowed.set(factory);
						throw failure;
					}

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						throw new AssertionError("costing must not run after factory binding failed");
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						throw new AssertionError("costing must not run after factory binding failed");
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
						throw new AssertionError("costing must not run after factory binding failed");
					}

					@Override
					public void close() {
						throw cleanup;
					}
				};
			}
		};
		IllegalStateException thrown = assertThrows(IllegalStateException.class, () -> PackedCascadesPlanner.optimize(
				new Join(pattern("a"), pattern("b")), OptimizationGoal.root(),
				new PackedPlannerLimits(100_000L, Long.MAX_VALUE, 10_000_000L), model));
		assertSame(failure, thrown);
		assertEquals(1, thrown.getSuppressed().length);
		assertSame(cleanup, thrown.getSuppressed()[0]);
		assertNotNull(borrowed.get());
		assertThrows(IllegalStateException.class, () -> borrowed.get().open());
	}

	private static void assertProviderFailure(Throwable failure) {
		IllegalStateException closeFailure = new IllegalStateException("actual provider close failure");
		AtomicReference<PackedPhysicalRegion> openedRegion = new AtomicReference<>();
		AtomicInteger closes = new AtomicInteger();
		PackedCostModel model = new PackedCostModel() {
			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				throw new AssertionError("session must handle estimation");
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {
					private PackedPhysicalRegion.Factory factory;

					@Override
					public void bindPhysicalRegions(PackedPhysicalRegion.Factory value) {
						factory = value;
					}

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						assertNotNull(factory);
						var region = factory.open();
						assertEquals(PackedPhysicalRegion.Status.READY, region.status());
						openedRegion.set(region.value());
						if (failure instanceof RuntimeException runtime) {
							throw runtime;
						}
						throw (Error) failure;
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						estimateLeaf(relationId, context, output);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
					}

					@Override
					public void close() {
						closes.incrementAndGet();
						throw closeFailure;
					}
				};
			}
		};
		Throwable thrown = assertThrows(Throwable.class, () -> PackedCascadesPlanner.optimize(
				new Join(pattern("a"), pattern("b")), OptimizationGoal.root(),
				new PackedPlannerLimits(100_000L, Long.MAX_VALUE, 10_000_000L), model));
		assertSame(failure, thrown);
		assertEquals(1, closes.get());
		assertEquals(1, thrown.getSuppressed().length);
		assertSame(closeFailure, thrown.getSuppressed()[0]);
		assertNotNull(openedRegion.get());
		assertThrows(IllegalStateException.class, () -> openedRegion.get().root());
	}

	private static StatementPattern pattern(String suffix) {
		return new StatementPattern(Var.of("s" + suffix), Var.of("p" + suffix), Var.of("o" + suffix));
	}

	private static PackedCostEstimate cost(double sourceRows) {
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setInclusivePhysicalCost(sourceRows, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
		return estimate;
	}

	private static PackedCostEstimate localCost(double sourceRows) {
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setLocalPhysicalCost(sourceRows, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
		return estimate;
	}
}
